void Require(bool ok, string message) { if (!ok) throw new System.InvalidOperationException(message); }
var session = TinyRiders.ThemedCollectionSession.Instance;
Require(session != null && session.IsReady && !SceneLoader.IsLoading, "Level is not ready.");
Require(session.Total == 1200 && session.LivePileCount == 1200 && session.ActiveDefinitions.Count() == 600 && session.Capacity == 1200, "Population or capacity changed.");
Require(session.State.instances.Select(r => r.id).Distinct().Count() == 1200, "Copy IDs must remain unique.");
Require(session.ActiveDefinitions.All(e => e.sortingItem.WorldItem && e.sortingItem.HandItem && e.sortingItem.PlacedOnShelfPrefab), "Missing required car wrapper.");
Require(WorldItemBase.All.GroupBy(w => w.Data.SaveId).Count() == 600 && WorldItemBase.All.GroupBy(w => w.Data.SaveId).All(g => g.Count() == 2), "Variant population changed.");
var renderers = UnityEngine.Object.FindObjectsByType<ItemVisualGroup>(UnityEngine.FindObjectsSortMode.None).SelectMany(g => g.Renderers).Where(r => r && r.enabled && r.gameObject.activeInHierarchy).ToArray();
Require(renderers.All(r => r.GetComponent<UnityEngine.MeshFilter>()?.sharedMesh != null && r.sharedMaterials.All(m => m != null)), "Missing live car mesh or material.");
var world = WorldItemBase.All.First(w => TinyRiders.ThemedWorldInstance.Read(w) != null);
string id = TinyRiders.ThemedWorldInstance.Read(world);
var definition = session.Definition(world.Data);
var shelf = UnityEngine.Object.FindObjectsByType<SortingShelf>(UnityEngine.FindObjectsSortMode.None).First(s => s.GetComponent<TinyRiders.ThemeShelfBinding>()?.themeId == definition.themeId);
Require(Player.Instance.ItemCollector.TryCollectItem(world), "Normal pickup failed.");
Require(Player.Instance.SortingBehaviour.TryGetHeldSortable(out var sortable), "Held car is not sortable.");
Require(shelf.CanAccept(sortable, 0, out var reason), "Shelf rejected car: " + reason);
Require(Player.Instance.SortingBehaviour.TryGetPlacedItemFromHand(out var placed), "Normal hand-to-shelf transfer failed.");
shelf.AddItem(placed, 0);
Require(session.Sorted == 1 && session.LivePileCount == 1199, "Sort did not update collection state.");
var save = UnityEngine.Object.FindFirstObjectByType<LevelSaveManager>();
Require(save.StorageKey == "StartupSpeed.QA.20261021", "Save isolation failed.");
save.Save();
var saved = UnityEngine.JsonUtility.FromJson<LevelSaveData>(UnityEngine.PlayerPrefs.GetString(save.StorageKey));
Require(saved.version == 3 && saved.themed.schema == 1 && saved.themed.instances.Count == 1200, "Save schema or population changed.");
var record = saved.themed.instances.Single(r => r.id == id);
Require(record.state == "sorted", "Sorted copy was not persisted.");
UnityEditor.SessionState.SetString("StartupSpeed.SortedId", id);
UnityEditor.SessionState.SetString("StartupSpeed.ShelfId", record.shelfId);
UnityEditor.SessionState.SetString("StartupSpeed.SlotId", record.slotId);
System.IO.File.WriteAllText("IntegrationEvidence/StartupLoadingSpeed/sorting-result.txt", "PASS: 600 variants, two copies each, 1200 cars and slots; unique copy IDs; required wrappers and live car meshes/materials present; normal pickup and correct placement; isolated save v3/themed schema 1 preserves 1200 records and sorted identity.\n");
SceneLoader.LoadWithLoadingScreen("Level", 0);
return "Sorting passed. Reloading once to verify saved progress restoration.";
